const fmt=n=>Number(n).toFixed(1).replace(/\.0$/,'');
const formulas=s=>h(s).replace(/\\times/g,' × ').replace(/\\quad/g,'　').replace(/\\,/g,' ');
let course, current=0, three=null, pipelineView=null, neuralView=null, notes=false, presenter=false;
