const figures={fig1:{title:'图 1 · 工作流程总览',page:1,caption:'作者原图：自监督预训练、少量示范与手表端个性化。图中显示的类别置信度是论文示意界面，不是本网页计算出的实验结果。'},fig2:{title:'图 2 · 四类动作的真实 IMU 窗口',page:4,caption:'作者原图：各运动复杂度的代表性 5 秒腕部 IMU 信号，来自文中公开数据集。'},fig3:{title:'图 3 · 汇总数据中的运动类型',page:4,caption:'作者原图：四类活动数据时长在汇总数据中的分布，不应视为全部用于预训练。'},fig4:{title:'论文图 4 · 自监督预训练流程',page:5,caption:'作者原图：腕部数据对齐、分块、遮挡、Transformer 编码及解码重建，属于预训练流程；这不是比较窗口长度的表 4。参阅论文 §4.1、PDF 第 5 页。'},fig5:{title:'图 5 · 手表端个人适配',page:6,caption:'作者原图：冻结编码器、个人动作示范、训练线性探针与实时识别。'},fig6:{title:'图 6 · 三个下游数据集',page:7,caption:'作者原图：不同标注窗口数下的平衡准确率及完整训练划分对比。'},fig7:{title:'图 7 · 八项 PrISM 过程任务',page:8,caption:'这是八项多步骤任务中，对短时间窗口所属步骤的分类结果，并非完整流程的识别或完成成功率。横轴是平衡准确率：先算每个步骤类别的召回率，再对各类别取平均；括号内是步骤类别数。灰色为使用9轴的PrISM基线，深蓝为3轴、浅蓝为6轴TransfHAR；使用完整训练划分，冻结编码器并训练线性探针。'},fig8:{title:'图 8 · 受试者的个人适配结果',page:9,caption:'作者原图：不同窗口数量下的用户研究结果，点显示受试者、线显示均值。'}};
const sourceByLesson={cover:'fig1',problem:'fig1',taxonomy:'fig2',window:'fig2',tokens:'fig4',mae:'fig4',encoder:'fig4',reconstruct:'fig4',probe:'fig5',offline:'fig6',study:'fig8',deployment:'fig5',federated:'fig5',limits:'fig7'};
const paperDefault={tokens:['figure','fig4'],mae:['page',5],encoder:['figure','fig4'],reconstruct:['page',6],probe:['figure','fig5'],offline:['figure','fig6'],study:['figure','fig8'],deployment:['page',6],federated:['page',6],limits:['figure','fig7']};
function inlineSourceUrl(kind,id){return kind==='figure'?`assets/${id}.webp`:`assets/pages/page-${String(id).padStart(2,'0')}.webp`}
let inlineZoom=100, inlineFigure='fig1', translationOpen=false;
function translationMarkup(page){const t=getPaperTranslation(page);if(!t)return '<p>这一页暂无中文对照。</p>';return `<h4>第 ${Number(page)} 页 · ${h(t.title)}</h4><p class="translation-scope">中文译文与译注，供阅读参考；图表细项及参考文献以左侧原文为准。</p>${t.paragraphs.map(p=>`<p>${h(p)}</p>`).join('')}`}
function syncTranslation(){const scroll=$('#inlineScroll'),panel=$('#paperTranslation'),toggle=$('#translationToggle'),grid=$('#inlinePaperGrid');if(!scroll||!panel||!toggle||!grid)return;const isPage=scroll.dataset.mode==='page',show=isPage&&translationOpen;toggle.hidden=!isPage;toggle.setAttribute('aria-pressed',String(show));panel.hidden=!show;grid.classList.toggle('show-translation',show);if(show)panel.innerHTML=translationMarkup($('#inlinePageSelect').value);document.body.classList.toggle('reading-translation',show&&!$('#stagePaper')?.hidden)}
function inlinePaper(l){
 const fallback=sourceByLesson[l.id]||'fig1',pd=paperDefault[l.id]||['figure',fallback];
 const startMode=pd[0]==='page'?'page':'figure',id=startMode==='figure'?pd[1]:fallback,f=figures[id];
 const page=startMode==='page'?pd[1]:f.page;
 const caption=startMode==='page'?`论文原文第 ${page} 页 · 可以用右上角 + / − 放大缩小。${l.id==='federated'?' 产品上线与版本更新为工程方案；论文图5展示的是原型。':''}`:`${f.title} · ${f.caption}`;
 return `<section class="inline-paper" id="inlinePaper" aria-label="当前章节论文原图与原文"><div class="inline-head"><div><span class="tiny-label">PAPER REFERENCE</span><h3>论文原图与原文</h3></div><span>页面内对照</span></div><div class="inline-tools"><button type="button" id="inlineFigureTab" class="${startMode==='figure'?'active':''}">原图</button><button type="button" id="inlinePageTab" class="${startMode==='page'?'active':''}">原文页</button><select id="inlinePageSelect" aria-label="选择论文原文页">${Array.from({length:16},(_,i)=>`<option value="${i+1}" ${i+1===page?'selected':''}>第 ${i+1} / 16 页</option>`).join('')}</select><button id="translationToggle" type="button" aria-pressed="${startMode==='page'&&translationOpen?'true':'false'}" ${startMode==='page'?'':'hidden'}>中文对照</button><button id="inlineZoomOut" type="button" aria-label="缩小原图">−</button><button id="inlineZoomIn" type="button" aria-label="放大原图">＋</button></div><div class="inline-caption" id="inlineCaption">${h(caption)}</div><div class="inline-paper-grid ${startMode==='page'&&translationOpen?'show-translation':''}" id="inlinePaperGrid"><div class="inline-scroll" id="inlineScroll" data-mode="${startMode}"><img id="inlinePaperImage" alt="${h(caption)}" data-src="${inlineSourceUrl(startMode,startMode==='page'?page:id)}" decoding="async"></div><aside class="paper-translation" id="paperTranslation" aria-label="本页中文对照" ${startMode==='page'&&translationOpen?'':'hidden'}>${startMode==='page'&&translationOpen?translationMarkup(page):''}</aside></div><div class="inline-credit">Bradshaw et al. · CC BY 4.0；可选择原图或原文页，在本页直接阅读。</div></section>`
}
function showInline(kind,id,scroll=true){const img=$('#inlinePaperImage'),panel=$('#inlinePaper');if(!img||!panel)return;setStage('paper');let label='';if(kind==='figure'){const f=figures[id];if(!f)return;inlineFigure=id;$('#inlinePageSelect').value=String(f.page);label=f.title+' · '+f.caption}else{let p=Math.max(1,Math.min(16,Number(id)||1));id=p;$('#inlinePageSelect').value=String(p);label=`论文原文第 ${p} 页 · 可以用右上角 + / − 放大缩小。`}img.src=inlineSourceUrl(kind,id);img.alt=label;$('#inlineScroll').dataset.mode=kind;$('#inlineCaption').textContent=label;$('#inlineFigureTab').classList.toggle('active',kind==='figure');$('#inlinePageTab').classList.toggle('active',kind==='page');inlineZoom=100;img.style.width='100%';$('#inlineScroll').classList.remove('zoomed');$('#inlineScroll').scrollTop=0;syncTranslation();if(scroll)panel.scrollIntoView({behavior:REDUCE_MOTION?'auto':'smooth',block:'center'})}
const figBtn=(id,label='查看论文原图 ↗')=>`<button class="evidence-link" type="button" data-figure="${id}">${label}</button>`;
const cardHead=(label,title,sub,tag='')=>`<div class="card-head"><div><div class="tiny-label">${label}</div><h2 class="card-title">${title}</h2><p class="card-subtitle">${sub}</p></div>${tag?`<span class="tag">${tag}</span>`:''}</div>`;
function cover(){return `<div class="card visual-card cover-card"><div class="cover-inner"><span class="cover-kicker">PAPER WALKTHROUGH · 30 MINUTES</span><h2>TransfHAR</h2><p class="cover-en">Self-Supervised Wrist Representations<br>for On-Demand Activity Recognition</p><div class="cover-rule"></div><p class="cover-authors">Aidan Bradshaw · Riku Arakawa · Xin Liu · Karan Ahuja</p><p class="cover-sub">腕部运动先验如何帮助手表认识用户自己的动作？</p><div class="cover-foot"><span>arXiv:2608.15861v2 · 2026</span><button class="evidence-link" type="button" data-page="1">打开论文首页 ↗</button></div></div></div>`}
const flowSteps={pretrain:[['分块','每轴128点经核大小、步长均为4的一维卷积，形成32个token；每个token有384个特征。'],['遮挡','选择约65%的位置遮挡；带自身时间与通道位置的可见token进入编码器。'],['可见编码','12层Transformer输出每个可见token的上下文化384维表示。'],['恢复位置','依据保存的遮挡位置插入可学习mask token，恢复解码器的位置结构。'],['重建损失','4层解码器重建片段；均方误差只在被遮挡位置计算。']],inference:[['分块','每轴128点经一维卷积得到32个token，给每个token加入时间与通道位置。'],['全部输入','推理时不遮挡，整个窗口的token进入冻结编码器。'],['编码器','12层Transformer让窗口内的不同时间和传感器轴交换信息。'],['平均池化','对所有编码后token的每一维分别求均值，得到384维窗口向量。'],['线性分类','个人线性头将384维向量映射到用户定义的类别；图中七条输出以论文用户研究的七类为例，并不表示预测分数。']]};
function showFlow(mode,index){const steps=flowSteps[mode];$('#networkPipeline').innerHTML=steps.map(([name],i)=>`<button type="button" data-flow-step="${i}" class="${i===index?'active':''}"><small>0${i+1}</small><span>${name}</span></button>`).join('');$('#flowExplanation').textContent=steps[index][1];$('#phaseCount').textContent=`步骤 ${index+1} / 5`}
function viewZoomTools(prefix){return `<div class="view-zoom" role="group" aria-label="图形缩放和视角"><span>视图</span><button type="button" id="${prefix}ZoomOut" aria-label="缩小图形">−</button><output id="${prefix}ZoomValue" aria-live="polite">100%</output><button type="button" id="${prefix}ZoomIn" aria-label="放大图形">＋</button><button type="button" class="view-reset" id="${prefix}ResetView">↺ 恢复视角</button><span class="view-hint">滚轮或触控板缩放 · 拖动旋转</span></div>`}
function networkCard(stage){
 const titles={tokens:['TOKENIZATION','从128个点到32个片段','逐轴分块，再给每个token加入时间与传感器身份'],mask:['MASKING','用三种遮挡建立学习任务','改变遮挡方式，比较哪些片段可进入编码器'],encoder:['VIT-1D ENCODER','展开12层编码器','对比预训练的可见片段与推理时全部片段'],reconstruct:['MAE DECODER','从可见片段到遮挡位置的训练目标','依次查看遮挡、插回mask token与计算损失']};
 const t=titles[stage],initialRun=stage==='tokens'||stage==='encoder'?'inference':'pretrain',runButtons=`<div class="segment" id="networkRun"><button data-run="pretrain" class="${initialRun==='pretrain'?'active':''}">预训练</button><button data-run="inference" class="${initialRun==='inference'?'active':''}">推理</button></div>`,maskButtons=stage==='mask'?`<div class="segment" id="maskPicker"><button data-mask="random" class="active">随机</button><button data-mask="time">时间</button><button data-mask="channel">通道</button></div>`:stage==='reconstruct'?`<div class="segment" id="phasePicker"><button data-phase="masked" class="active">1 遮挡</button><button data-phase="restore">2 插入标记</button><button data-phase="loss">3 损失位置</button></div>`:'';
 const options=stage==='encoder'?`<label class="network-slider">层间距 <input id="layerGap" type="range" min="0" max="2" step="0.1" value="1" aria-label="调整编码器层间距"></label>`:`<label class="network-select">传感器 <select id="channelSelect"><option value="0">acc X</option><option value="1">acc Y</option><option value="2">acc Z</option><option value="3">gyro X</option><option value="4">gyro Y</option><option value="5">gyro Z</option></select></label><label class="network-slider">片段 <input id="tokenIndex" type="range" min="1" max="32" value="1" aria-label="选择时间片段"><span id="tokenIndexText">1 / 32</span></label>`;
 return `<div class="card visual-card dark network-card">${cardHead(t[0],t[1],t[2],'Three.js')}<div class="visual-body"><div class="controls-row"><div class="segment" id="maeAxes"><button data-axis="3">3 轴</button><button data-axis="6" class="active">6 轴</button></div>${runButtons}${maskButtons}</div><div class="network-shape-trace" id="networkShapeTrace" aria-live="polite"></div><p class="network-shape-note" id="networkShapeNote"></p><div class="flow-playback"><button type="button" id="playSteps">▷ 播放流程</button><button type="button" id="prevStep">← 上一步</button><button type="button" id="nextStep">下一步 →</button><button type="button" id="resetSteps">重置</button><button type="button" id="modelFocus" aria-pressed="false">⛶ 放大演示</button><span id="phaseCount">步骤 1 / 5</span></div><div class="process-strip" id="networkPipeline" aria-label="流程步骤"></div><p class="flow-explanation" id="flowExplanation"></p><div class="canvas-stage-labels"><span>01 · 输入 token 网格（通道 × 时间）</span><span>02 · 编码器 · 12层</span><span id="stageOutput">${initialRun==='inference'?'03 · 池化 384维':'03 · 轻量解码器'}</span><span id="stageFinal">${initialRun==='inference'?'04 · 线性头（7类示例）':'04 · 遮挡损失'}</span></div><div class="mae-canvas-wrap"><canvas class="mae-canvas" id="maeCanvas" role="img" aria-label="可旋转三维示意：token 网格、12层编码器隧道，以及解码重建或池化与线性头"></canvas><div class="canvas-legend"><span><i class="swatch"></i>可见（按通道着色）</span><span><i class="swatch mask"></i>遮挡</span><span><i class="swatch layer"></i>编码器</span><span><i class="swatch decoder"></i>mask标记 / 解码器</span><span><i class="swatch loss"></i>损失位置</span></div><div class="canvas-hint">拖动旋转 · 滚轮缩放 · 点击任意 token 追踪 ｜ 左：输入网格 → 中：12层编码器 → 右：${initialRun==='inference'?'池化与分类':'解码重建与损失'}</div></div>${viewZoomTools("model")}<div class="channel-legend"><span style="--channel:#c98a5e">acc X</span><span style="--channel:#d9b380">acc Y</span><span style="--channel:#c99a72">acc Z</span><span class="gyro-label" style="--channel:#8aa9a0">gyro X</span><span class="gyro-label" style="--channel:#a8bcb2">gyro Y</span><span class="gyro-label" style="--channel:#8aa9a0">gyro Z</span></div><div class="network-flow"><span>32 token / 轴</span><span>→</span><span>12层 Transformer</span><span>→</span><span id="flowLast">${stage==='encoder'?'384维池化表示':stage==='tokens'?'窗口表示':'4层解码器（训练）'}</span></div><div class="network-control-row">${options}</div><div class="network-inspector" id="modelInspector" aria-live="polite">正在准备结构示意…</div><div class="controls-row"><span class="mode-note" id="maskInfo"></span>${figBtn('fig4')}</div><p class="mode-note">三维结构与遮挡位置为教学示意，不包含论文模型权重、真实样本值或注意力权重；取整可能使显示遮挡率与65%略有差异。</p></div></div>`
}
function overview(){return `<div class="card visual-card">${cardHead('THE PAPER IN ONE VIEW','先学运动，再学习你的动作','从预训练到个人识别的两阶段路径','原文图 1')}<div class="visual-body"><div class="image-frame overview-img"><img src="assets/fig1.webp" alt="论文图1：从预训练到个人活动识别的整体流程" width="1283" height="263" decoding="async" loading="lazy"></div><div class="flowbar"><div class="flow-node"><b>01 · 自监督预训练</b><small>大规模 L1/L2 腕部 IMU<br>不使用动作标签</small></div><div class="flow-arrow">→</div><div class="flow-node"><b>02 · 用户个性化</b><small>冻结编码器 + 线性探针<br>少量有标签示范</small></div></div>${figBtn('fig1')}<p class="evidence-note">原图 © Bradshaw et al., 2026 · CC BY 4.0；网页图示与讲解基于用户提供的 v2 论文。</p></div></div>`}
